import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_range(start, end):
    if start > end:
        return 1
    result = start
    for i in range(start + 1, end + 1):
        result = lcm(result, i)
    return result

def check_weakly_increasing(n, max_k=100):
    print(f"--- Checking n = {n} ---")
    is_increasing = True
    all_check = True

    # Check for k=1 to max_k - 1
    for k in range(1, max_k):
        x_k = lcm_range(k, k + n - 1)
        x_k_plus_1 = lcm_range(k + 1, k + n)

        if x_k_plus_1 <= x_k:
            is_increasing = False
            all_check = False
            print(f"FAILURE at k={k}: x_{k+1} ({x_k_plus_1}) <= x_k ({x_k})")
            # Store the first failure point if found, but continue the loop for logging

        if k == 1:
             print(f"k=1: x_1 = {x_k}")
             print(f"k=1: x_2 = {x_k_plus_1}")

    if is_increasing and all_check:
        print(f"Check for k=1 to {max_k-1}: Sequence appears strictly increasing.")
    elif all_check and not is_increasing:
        # This case shouldn't happen if is_increasing is defined correctly, but for clarity
        print(f"Check for k=1 to {max_k-1}: Sequence failed to be strictly increasing.")
    else:
        print(f"Check for k=1 to {max_k-1}: Sequence failed to be strictly increasing (First failure logged above).")

    return is_increasing

# Check n=3, 4, 5 up to k=100
for n in [3, 4, 5]:
