import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def calculate_xk(k, n):
    if n == 0:
        return 1
    return lcm_list(range(k, k + n))

# Test cases
N_values = [1, 2, 3, 4]
K_tests = [1, 2, 3, 5, 10]
results = {}

for n in N_values:
    results[n] = {}
    print(f"--- Testing n = {n} ---")
    for k in K_tests:
        xk = calculate_xk(k, n)
        xk_plus_1 = calculate_xk(k + 1, n)
        is_increasing = xk_plus_1 > xk

        results[n][k] = {
            "x_k": xk,
            "x_k+1": xk_plus_1,
            "increasing": is_increasing
        }
        print(f"k={k}: x_k={xk}, x_{k+1}={xk_plus_1}, increasing={is_increasing}")

# Display structured results
import json
print("\n--- Structured Results ---")
print(json.dumps(results, indent=4))

